using FamilyVeda.Application.Portal;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace FamilyVeda.Api.Controllers;

[Route("api/v1")]
[Authorize]
public sealed class FamilyDoctorController(IFamilyDoctorService familyDoctorService) : ApiControllerBase
{
    [HttpGet("doctors/directory")]
    [Authorize(Policy = "FamilyUser")]
    public async Task<ActionResult<IReadOnlyList<DoctorSummaryDto>>> GetDirectory(string? search, string? district, CancellationToken cancellationToken) =>
        Ok(await familyDoctorService.GetDirectoryAsync(search, district, cancellationToken));

    [HttpGet("families/{familyId:guid}/doctor")]
    [Authorize(Policy = "FamilyUser")]
    public async Task<ActionResult<DoctorSummaryDto>> GetCurrent(Guid familyId, CancellationToken cancellationToken)
    {
        var doctor = await familyDoctorService.GetCurrentAsync(familyId, cancellationToken);
        return doctor is null ? NoContent() : Ok(doctor);
    }

    [HttpPost("families/{familyId:guid}/doctor-requests")]
    [Authorize(Policy = "FamilyUser")]
    public async Task<ActionResult<DoctorRequestDto>> RequestDoctor(Guid familyId, CreateDoctorRequest request, CancellationToken cancellationToken)
    {
        var result = await familyDoctorService.RequestAsync(familyId, request, cancellationToken);
        return Created($"/api/v1/families/{familyId}/doctor-requests/{result.Id}", result);
    }

    [HttpGet("families/{familyId:guid}/doctor-requests/pending")]
    [Authorize(Policy = "FamilyUser")]
    public async Task<ActionResult<DoctorRequestDto>> GetPending(Guid familyId, CancellationToken cancellationToken)
    {
        var request = await familyDoctorService.GetPendingAsync(familyId, cancellationToken);
        return request is null ? NoContent() : Ok(request);
    }

    [HttpPost("families/{familyId:guid}/doctor-requests/{id:guid}/cancel")]
    [Authorize(Policy = "FamilyUser")]
    public async Task<ActionResult<DoctorRequestDto>> Cancel(Guid familyId, Guid id, CancellationToken cancellationToken) =>
        Ok(await familyDoctorService.CancelAsync(familyId, id, cancellationToken));

    [HttpGet("doctors/me/family-requests")]
    [Authorize(Policy = "Doctor")]
    public async Task<ActionResult<IReadOnlyList<DoctorRequestDto>>> GetMyRequests(CancellationToken cancellationToken) =>
        Ok(await familyDoctorService.GetMyRequestsAsync(cancellationToken));

    [HttpPost("doctors/me/family-requests/{id:guid}/accept")]
    [Authorize(Policy = "Doctor")]
    public async Task<ActionResult<DoctorRequestDto>> Accept(Guid id, CancellationToken cancellationToken) =>
        Ok(await familyDoctorService.AcceptAsync(id, cancellationToken));

    [HttpPost("doctors/me/family-requests/{id:guid}/decline")]
    [Authorize(Policy = "Doctor")]
    public async Task<ActionResult<DoctorRequestDto>> Decline(Guid id, CancellationToken cancellationToken) =>
        Ok(await familyDoctorService.DeclineAsync(id, cancellationToken));
}
